from collections import deque


def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    parent_fwd = {start: None}
    parent_bwd = {goal: None}
    q_fwd = deque([start])
    q_bwd = deque([goal])

    def expand(queue, parents, other):
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in parents:
                    parents[(nr, nc)] = (r, c)
                    if (nr, nc) in other:
                        return (nr, nc)
                    queue.append((nr, nc))
        return None

    meet = None
    while q_fwd and q_bwd:
        meet = expand(q_fwd, parent_fwd, parent_bwd)
        if meet:
            break
        meet = expand(q_bwd, parent_bwd, parent_fwd)
        if meet:
            break
    if meet is None:
        return []
    left = []
    node = meet
    while node is not None:
        left.append(node)
        node = parent_fwd[node]
    left.reverse()
    node = parent_bwd[meet]
    while node is not None:
        left.append(node)
        node = parent_bwd[node]
    return left

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def neighbours(cell):
        r, c = cell
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    front_s, front_g = {start}, {goal}
    par_s, par_g = {start: None}, {goal: None}
    meet = None
    while front_s and front_g and meet is None:
        if len(front_s) <= len(front_g):
            nxt = set()
            for cell in front_s:
                for nb in neighbours(cell):
                    if nb not in par_s:
                        par_s[nb] = cell
                        nxt.add(nb)
                        if nb in par_g:
                            meet = nb
            front_s = nxt
        else:
            nxt = set()
            for cell in front_g:
                for nb in neighbours(cell):
                    if nb not in par_g:
                        par_g[nb] = cell
                        nxt.add(nb)
                        if nb in par_s:
                            meet = nb
            front_g = nxt
    if meet is None:
        return []
    path = []
    node = meet
    while node is not None:
        path.append(node)
        node = par_s[node]
    path.reverse()
    node = par_g[meet]
    while node is not None:
        path.append(node)
        node = par_g[node]
    return path

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    max_depth = rows * cols
    depth_limit = 1
    while depth_limit <= max_depth:
        stack = [(start, 0, [start])]
        best_depth = {start: 0}
        cut = False
        while stack:
            cell, depth, path = stack.pop()
            if cell == goal:
                return path
            if depth >= depth_limit:
                cut = True
                continue
            r, c = cell
            for nr, nc in ((r, c - 1), (r, c + 1), (r - 1, c), (r + 1, c)):
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    if best_depth.get((nr, nc), max_depth + 1) > depth + 1:
                        best_depth[(nr, nc)] = depth + 1
                        stack.append(((nr, nc), depth + 1, path + [(nr, nc)]))
        if not cut:
            return []
        depth_limit += 1
    return []

import sys


def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    sys.setrecursionlimit(max(10000, rows * cols * 4))
    free_cells = sum(row.count('.') for row in grid)

    def dls(cell, depth, limit, best, path, state):
        if cell == goal:
            return True
        if depth == limit:
            state[0] = True
            return False
        r, c = cell
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                nb = (nr, nc)
                if best.get(nb, 1 << 30) <= depth + 1:
                    continue
                best[nb] = depth + 1
                path.append(nb)
                if dls(nb, depth + 1, limit, best, path, state):
                    return True
                path.pop()
        return False

    for limit in range(1, free_cells + 1):
        best = {start: 0}
        path = [start]
        state = [False]
        if dls(start, 0, limit, best, path, state):
            return path
        if not state[0]:
