    pq_b = [(0, t)]
    done_f = [False] * n
    done_b = [False] * n
    best = INF
    while pq_f and pq_b:
        if pq_f[0][0] + pq_b[0][0] >= best:
            break
        if pq_f[0][0] <= pq_b[0][0]:
            d, u = heapq.heappop(pq_f)
            if done_f[u]:
                continue
            done_f[u] = True
            for v, w in fwd[u]:
                if d + w < dist_f[v]:
                    dist_f[v] = d + w
                    heapq.heappush(pq_f, (d + w, v))
                if dist_b[v] < INF:
                    best = min(best, d + w + dist_b[v])
        else:
            d, u = heapq.heappop(pq_b)
