def solve(nums, k):
    def partition(arr, left, right, pivot_idx):
        pivot = arr[pivot_idx]
        arr[pivot_idx], arr[right] = arr[right], arr[pivot_idx]
        store_idx = left
        for i in range(left, right):
            if arr[i] < pivot:
                arr[store_idx], arr[i] = arr[i], arr[store_idx]
                store_idx += 1
        arr[right], arr[store_idx] = arr[store_idx], arr[right]
        return store_idx

    def select(arr, left, right, k):
        if left == right:
            return arr[left]
        pivot_idx = partition(arr, left, right, median_of_medians(arr, left, right))
        if k == pivot_idx:
            return arr[k]
        elif k < pivot_idx:
            return select(arr, left, pivot_idx - 1, k)
        else:
            return select(arr, pivot_idx + 1, right, k)

    def median_of_medians(arr, left, right):
        group_size = 5
        num_groups = (right - left + 1 + group_size - 1) // group_size
        medians = []
        for i in range(num_groups):
            group_start = left + i * group_size
            group_end = min(group_start + group_size - 1, right)
            group = arr[group_start:group_end + 1]
            group.sort()
            medians.append(group[len(group) // 2])
        medians.sort()
        return left + medians.index(medians[len(medians) // 2])

    return select(nums, 0, len(nums) - 1, k - 1)

