        return []

    # Union-Find (Disjoint Set Union) data structure
    class DSU:
        def __init__(self, size):
            self.parent = list(range(size))
            self.size = [1] * size

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            x_root = self.find(x)
            y_root = self.find(y)
            if x_root == y_root:
                return
            if self.size[x_root] < self.size[y_root]:
                x_root, y_root = y_root, x_root
            self.parent[y_root] = x_root
            self.size[x_root] += self.size[y_root]

    # Create a mapping from interval endpoints to unique indices
    unique_points = sorted(set([p for interval in intervals for p in interval]))
    point_to_index = {p: i for i, p in enumerate(unique_points)}

    # Initialize DSU
    dsu = DSU(len(unique_points))

    # Union intervals that overlap or touch
    for start, end in intervals:
        start_idx = point_to_index[start]
        end_idx = point_to_index[end]
        # Union all points between start and end
        for i in range(start_idx, end_idx + 1):
            if i + 1 <= end_idx:
                dsu.union(i, i + 1)

    # Find the representative of each component
    components = {}
    for i in range(len(unique_points)):
        root = dsu.find(i)
        if root not in components:
            components[root] = [unique_points[i], unique_points[i]]
        else:
            components[root][1] = max(components[root][1], unique_points[i])

    # Sort the merged intervals by start
    merged = sorted(components.values())
    return merged

