def solve(nums, target):
    def binary_search_left(nums, target):
        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                right = mid - 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    def binary_search_right(nums, target):
        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    if not nums:
        return [-1, -1]

    # Exponential search
    n = len(nums)
    if nums[0] == target:
        first = 0
    else:
        first = 1
        while first < n and nums[first] < target:
            first *= 2

    # Binary search between [first//2, min(first, n-1)]
    left = first // 2
    right = min(first, n - 1)
    first_index = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            first_index = mid
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    if first_index == -1:
        return [-1, -1]

    # Find last occurrence
    left = first_index
    right = n - 1
    last_index = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            last_index = mid
            left = mid + 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return [first_index, last_index]

