def solve(nums, k):
    from collections import Counter

    # Count the frequency of each number
    freq = Counter(nums)

    # Bucket sort by frequency: bucket index is the frequency
    # Each bucket contains numbers with that frequency
    buckets = {}
    for num, count in freq.items():
        if count not in buckets:
            buckets[count] = []
        buckets[count].append(num)

    # Get the frequencies in descending order
    sorted_freqs = sorted(buckets.keys(), reverse=True)

    # Collect the results
    result = []
    for freq in sorted_freqs:
        result.extend(buckets[freq])
        if len(result) >= k:
            return result[:k]

