def solve(n, edges):
    def count_edges(component):
        edge_count = 0
        for u, v in edges:
            if u in component or v in component:
                edge_count += 1
        return edge_count

    def is_cycle(component):
        if len(component) == 1:
            return False
        return count_edges(component) >= len(component)

    visited = set()
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for start in range(n):
        if start not in visited:
            stack = [start]
            visited.add(start)
            component = {start}
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        component.add(neighbor)
                        stack.append(neighbor)
            if is_cycle(component):
                return True
    return False

def solve(n, edges):
    def count_edges(component):
        return sum(len(edges) for u in component for v in edges if u == v or v == u)

    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    components = []

    def dfs(u, component):
        visited[u] = True
        component.append(u)
        for v in graph[u]:
            if not visited[v]:
                dfs(v, component)

    for i in range(n):
        if not visited[i]:
            component = []
            dfs(i, component)
            components.append(component)

    for comp in components:
        edge_count = 0
        nodes = len(comp)
        for u in comp:
            edge_count += len(graph[u])
        if edge_count > 2 * nodes - 2:
            return True
    return False

def solve(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    comp = [-1] * n
    c = 0
    for s in range(n):
        if comp[s] != -1:
            continue
        comp[s] = c
        stack = [s]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if comp[v] == -1:
                    comp[v] = c
                    stack.append(v)
        c += 1
    nodes = [0] * c
    edge_cnt = [0] * c
    for u in range(n):
        nodes[comp[u]] += 1
    for u, v in edges:
        edge_cnt[comp[u]] += 1
    return any(edge_cnt[i] >= nodes[i] for i in range(c))
